\usetikzlibrary{calc,angles,quotes}
\begin{tikzpicture}[x=1cm,y=1cm,draw=black,text=black,line width=0.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
% Complete squares, constructed from perpendicular equal side vectors.
\coordinate (D) at (0,0);
\coordinate (C) at ({4*cos(34)},{4*sin(34)});
\coordinate (A) at ({-4*sin(34)},{4*cos(34)});
\coordinate (B) at ($(A)+(C)-(D)$);
\coordinate (P) at ($(D)!0.20!(C)$);
\pgfmathsetmacro{\smallSide}{3.2*cos(22)}
\coordinate (R) at ($(P)+({\smallSide*cos(12)},{\smallSide*sin(12)})$);
\coordinate (T) at ($(P)+({-\smallSide*sin(12)},{\smallSide*cos(12)})$);
\coordinate (S) at ($(R)+(T)-(P)$);
\coordinate (X) at (intersection cs:first line={(B)--(C)},second line={(T)--(S)});
\draw (A)--(B)--(C)--(D)--cycle;
\draw (P)--(R)--(S)--(T)--cycle;
\pic[draw,line width=0.4pt,angle radius=5mm,angle eccentricity=1.65,"$68^\circ$"] {angle=B--X--T};
\pic[draw,line width=0.4pt,angle radius=4mm,angle eccentricity=1.55,"$b$"] {angle=C--P--T};
\pic[draw,line width=0.4pt,angle radius=4mm,angle eccentricity=1.55,"$a$"] {angle=P--C--R};
\end{tikzpicture}

% mathsmap-diagram-colours {"version":1,"kind":"geometry","base":[],"semantic":[],"reference":"source page 44 p44-q4-b-diagram"}
\usetikzlibrary{calc,angles,quotes}
\begin{tikzpicture}[x=1cm,y=1cm,draw=black,text=black,line width=0.8pt,font=\fontsize{10}{12}\selectfont]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\coordinate (L) at (0,0);
\coordinate (R) at (6,0);
\coordinate (T) at (3,{3*sqrt(3)});
% Points derived from the equilateral outline and supplied angle relationships.
\coordinate (U) at ($(L)!0.72!(T)$);
\pgfmathsetmacro{\ux}{2.16}
\pgfmathsetmacro{\uy}{2.16*sqrt(3)}
\pgfmathsetmacro{\vx}{(6*sqrt(3)-\uy-tan(28)*\ux)/(sqrt(3)-tan(28))}
\pgfmathsetmacro{\vy}{sqrt(3)*(6-\vx)}
\coordinate (V) at (\vx,\vy);
\pgfmathsetmacro{\wx}{\vx-\vy/tan(58)}
\coordinate (W) at (\wx,0);
\pgfmathsetmacro{\kx}{\wx*tan(25)/(sqrt(3)+tan(25))}
\coordinate (K) at (\kx,{sqrt(3)*\kx});
\draw (L)--(R)--(T)--cycle;
\draw (U)--(V)--(W)--(K);
\pic[draw,line width=0.4pt,angle radius=4mm,angle eccentricity=1.65,"$88^\circ$"] {angle=V--U--T};
\pic[draw,line width=0.4pt,angle radius=4mm,angle eccentricity=1.65,"$85^\circ$"] {angle=W--K--U};
\pic[draw,line width=0.4pt,angle radius=4mm,angle eccentricity=1.5,"$a$"] {angle=U--V--W};
\pic[draw,line width=0.4pt,angle radius=4mm,angle eccentricity=1.55,"$b$"] {angle=V--W--K};
\pic[draw,line width=0.4pt,angle radius=5mm,angle eccentricity=1.55,"$58^\circ$"] {angle=R--W--V};
\end{tikzpicture}
